  "Next receipt": "அடுத்த ரசீது",
  "No account, no ads, no tracking. Receipts are read on this phone. The only things Tally downloads are its own files; a Google Sheets link is fetched only when you paste one.": "கணக்கு இல்லை, விளம்பரம் இல்லை, கண்காணிப்பு இல்லை. ரசீதுகள் இந்தக் கைப்பேசியிலேயே படிக்கப்படுகின்றன. Tally பதிவிறக்குவது தன் சொந்தக் கோப்புகளை மட்டுமே; Google Sheets இணைப்பை நீங்கள் ஒட்டும்போது மட்டுமே அது எடுக்கப்படும்.",
  "No account, no ads. Your data never leaves this phone unless you export it.": "கணக்கு இல்லை, விளம்பரம் இல்லை. நீங்கள் ஏற்றுமதி செய்யாவிட்டால் உங்கள் தரவு இந்தக் கைப்பேசியை விட்டு வெளியேறாது.",
  "No bills yet.": "இன்னும் பில்கள் இல்லை.",
  "No receipt? Add by hand": "ரசீது இல்லையா? கையால் சேர்",
  "No receipt? Type the amount and pick a category. Sums like 12.50+8 work too.": "ரசீது இல்லையா? தொகையை உள்ளிட்டு வகையைத் தேர்ந்தெடுங்கள். 12.50+8 போன்ற கூட்டலும் வேலை செய்யும்.",
  "No spending in {0}.": "{0}-இல் செலவு இல்லை.",
  "No total found. Type the total from the receipt.": "மொத்தம் கிடைக்கவில்லை. ரசீதில் உள்ள மொத்தத்தை உள்ளிடுங்கள்.",
  "No transactions yet. Scan a receipt or tap Add.": "இன்னும் பரிவர்த்தனைகள் இல்லை. ரசீதை ஸ்கேன் செய்யுங்கள் அல்லது சேர் தட்டுங்கள்.",
  "No-spend day": "செலவில்லா நாள்",
  "Not backed up yet": "இன்னும் காப்புப்பிரதி இல்லை",
