  "Old Excel files (.xls) are not supported. Open it and save as .xlsx or CSV.": "பழைய Excel கோப்புகள் (.xls) ஏற்கப்படாது. அதைத் திறந்து .xlsx அல்லது CSV-ஆகச் சேமியுங்கள்.",
