  "Scan a receipt": "ரசீதை ஸ்கேன் செய்",
  "Scan a receipt first: its items come with a category you can change.": "முதலில் ஒரு ரசீதை ஸ்கேன் செய்யுங்கள்: அதன் பொருட்கள், நீங்கள் மாற்றக்கூடிய வகையுடன் வரும்.",
