  "Your first entry. Nice start!": "உங்கள் முதல் பதிவு. நல்ல தொடக்கம்!",
  "Your first receipt, item by item. Nice!": "உங்கள் முதல் ரசீது, பொருள் பொருளாக. அருமை!",
