  "An estimate from categories and receipt words, with this year's usual limits. Check the LHDN rules before you claim, and keep the receipts.": "வகைகளையும் ரசீதுச் சொற்களையும் வைத்து, இந்த ஆண்டின் வழக்கமான வரம்புகளுடன் ஒரு மதிப்பீடு. கோருவதற்கு முன் LHDN விதிகளைச் சரிபாருங்கள், ரசீதுகளை வைத்திருங்கள்.",
  "Appears after a few days of spending.": "சில நாட்கள் செலவுக்குப் பிறகு தெரியும்.",
