  "Appears once an item is on 3 receipts.": "ஒரு பொருள் 3 ரசீதுகளில் வந்ததும் தெரியும்.",
  "Appears once entries have a time of day.": "பதிவுகளுக்கு நேரம் இருந்தால் தெரியும்.",
  "Appears when scanned receipts show SST or a service charge.": "ஸ்கேன் செய்த ரசீதுகளில் SST அல்லது சேவைக் கட்டணம் இருந்தால் தெரியும்.",
