  "Spent so far, bills still due, and your everyday pace. One-off big buys count once.": "இதுவரை செலவு, இன்னும் செலுத்த வேண்டிய பில்கள், உங்கள் அன்றாட வேகம். ஒருமுறை வாங்கும் பெரிய பொருட்கள் ஒருமுறைதான் கணக்கில் வரும்.",
  "Spent {0} more than came in": "வந்ததைவிட {0} அதிகம் செலவு செய்தீர்கள்",
