  "Zakat and fitrah (tax rebate)": "ஜகாத், ஃபித்ரா (வரித் தள்ளுபடி)",
  "{0} of {1} in your book. One for each day you log; a missed day never takes one away.": "உங்கள் புத்தகத்தில் {1}-இல் {0}. நீங்கள் பதியும் ஒவ்வொரு நாளுக்கும் ஒன்று; விடுபட்ட நாள் ஒருபோதும் ஒன்றைப் பறிக்காது.",
