  "A receipt is waiting for the reader. Open Scan when you are on Wi-Fi.": "ஒரு ரசீது படிப்பானுக்காகக் காத்திருக்கிறது. Wi-Fi-இல் இருக்கும்போது ஸ்கேனைத் திறங்கள்.",
