  "All of {0}": "{0} முழுவதும்",
  "Only someone with this password can open the file. If you forget it, the backup cannot be opened: no one can reset it.": "இந்தக் கடவுச்சொல் உள்ளவர் மட்டுமே கோப்பைத் திறக்க முடியும். அதை மறந்தால், காப்புப்பிரதியைத் திறக்க முடியாது: யாராலும் மீட்டமைக்க முடியாது.",
  "Open": "திற",
  "Password": "கடவுச்சொல்",
  "Password (optional)": "கடவுச்சொல் (விருப்பத்தேர்வு)",
  "Protect with a password": "கடவுச்சொல்லால் பாதுகா",
  "Protected backup": "பாதுகாக்கப்பட்ட காப்புப்பிரதி",
  "This protected backup was made by a newer Tally. Update Tally and try again.": "இந்தப் பாதுகாக்கப்பட்ட காப்புப்பிரதி Tally-இன் புதிய பதிப்பால் உருவானது. Tally-ஐப் புதுப்பித்து மீண்டும் முயலுங்கள்.",
  "Use at least 6 characters.": "குறைந்தது 6 எழுத்துகள் பயன்படுத்துங்கள்.",
  "Wrong password, or the file was changed.": "தவறான கடவுச்சொல், அல்லது கோப்பு மாற்றப்பட்டுள்ளது.",
  "Not linked to a purchase": "எந்த வாங்குதலுடனும் இணைக்கப்படவில்லை",
