  "Refunded": "பணம் திரும்பியது",
  "Refunded {0} on {1}": "{1} அன்று {0} திரும்பியது",
  "+ Add an account…": "+ கணக்கு சேர்…",
  "Use the result {0}": "விடை {0}-ஐப் பயன்படுத்து",
  "Home reminds you 2 days before the return window ends and a month before the warranty does.": "திருப்பித் தரும் காலம் முடிவதற்கு 2 நாள் முன்பும், உத்தரவாதம் முடிவதற்கு ஒரு மாதம் முன்பும் முகப்பு நினைவூட்டும்.",
  "Remind me before the return window ends ({0})": "திருப்பித் தரும் காலம் முடியும் முன் நினைவூட்டு ({0})",
  "Remind me before the warranty ends ({0})": "உத்தரவாதம் முடியும் முன் நினைவூட்டு ({0})",
  "Return by": "திருப்பக் கெடு",
  "Return or warranty reminder": "திருப்பித் தருதல் அல்லது உத்தரவாத நினைவூட்டல்",
  "Warranty until": "உத்தரவாதம் வரை",
  "{0}: return or exchange by {1}": "{0}: {1}-க்குள் திருப்பித் தரலாம் அல்லது மாற்றலாம்",
  "{0}: warranty ends {1}": "{0}: உத்தரவாதம் {1} அன்று முடியும்",
  "Could not get the rate (offline?). Type the rate from your bank app.": "விகிதத்தைப் பெற முடியவில்லை (இணையம் இல்லையா?). உங்கள் வங்கிச் செயலியில் உள்ள விகிதத்தை உள்ளிடுங்கள்.",
  "European Central Bank rate for {0}. Change it to your bank's rate if you like.": "{0}-க்கான European Central Bank விகிதம். விரும்பினால் உங்கள் வங்கியின் விகிதத்துக்கு மாற்றுங்கள்.",
  "Get today's rate": "இன்றைய விகிதத்தைப் பெறு",
