  "Savings goals: a target, a date and the account it grows in, with how much a month gets you there": "சேமிப்பு இலக்குகள்: ஒரு இலக்கு, ஒரு தேதி, அது வளரும் கணக்கு, மாதம் எவ்வளவு சேர்த்தால் அடையலாம் என்பதுடன்",
  "\"Can I afford it?\" now counts your everyday money, not your savings": "\"வாங்க முடியுமா?\" இப்போது உங்கள் சேமிப்பை அல்ல, அன்றாடப் பணத்தைக் கணக்கிடுகிறது",
  "Tamil is new. Suggest a better word": "தமிழ் புதிது. சிறந்த சொல்லைப் பரிந்துரையுங்கள்",
  "Tamil (beta): Tally in தமிழ். Suggest a better word from Settings": "தமிழ் (beta): Tally இப்போது தமிழில். சிறந்த சொல்லை அமைப்புகளில் பரிந்துரையுங்கள்",
  "\"Remind\" opens WhatsApp with a message for you to send; Tally sends nothing itself.": "\"நினைவூட்டு\" நீங்கள் அனுப்ப ஒரு செய்தியுடன் WhatsApp-ஐத் திறக்கும்; Tally தானாக எதையும் அனுப்பாது.",
  "(same day)": "(அதே நாள் வரை)",
  "About 1 day of your usual spending.": "சுமார் 1 நாள் வழக்கமான செலவுக்குச் சமம்.",
  "About {0} days of your usual spending.": "சுமார் {0} நாள் வழக்கமான செலவுக்குச் சமம்.",
