  "Bills and subscriptions: {0} a month, {1} a year": "பில்களும் சந்தாக்களும்: மாதம் {0}, ஆண்டுக்கு {1}",
  "Days with nothing spent": "எதுவும் செலவழிக்காத நாட்கள்",
  "Days you logged": "நீங்கள் பதிவு செய்த நாட்கள்",
  "From your own receipts in the last 6 months: the price on the day you last bought it at each shop.": "கடந்த 6 மாதங்களில் உங்கள் சொந்த ரசீதுகளிலிருந்து: ஒவ்வொரு கடையிலும் நீங்கள் கடைசியாக வாங்கிய நாளின் விலை.",
  "Hi {0}, a small reminder: {1} for the bill we split. Thanks!": "வணக்கம் {0}, ஒரு சிறிய நினைவூட்டல்: நாம் பகிர்ந்த பில்லுக்கு {1}. நன்றி!",
  "In the week after payday you spend {0}× your usual week: {1} against {2}.": "சம்பள நாளுக்குப் பிந்தைய வாரத்தில், வழக்கமான வாரத்தின் {0}× செலவழிக்கிறீர்கள்: {1}, வழக்கமாக {2}.",
