  "Scanned receipts are split item by item, each with its share of SST and charges. Payments without items show their shop.": "ஸ்கேன் செய்த ரசீதுகள் பொருள் வாரியாகப் பிரிக்கப்படும், ஒவ்வொன்றுக்கும் SST மற்றும் கட்டணங்களின் பங்குடன். பொருட்கள் இல்லாத கட்டணங்கள் கடையின் பெயரைக் காட்டும்.",
